SELECT (SELECT count(*) FROM sqlite_schema WHERE type='table' AND name NOT LIKE 'sqlite_%') AS table_count, (SELECT sql FROM sqlite_schema WHERE type='table' AND name='t1') AS t1_schema, (SELECT sql FROM sqlite_schema WHERE type='table' AND name='t2') AS t2_schema, (SELECT count(*) FROM t1) AS t1_rows, (SELECT group_concat(a || ':' || b, ',') FROM (SELECT a, b FROM t2 ORDER BY a, b)) AS t2_rows;